			/* based on https://github.com/Paul-Browne/image-comparison-slider */

			.slider {
			    position: absolute;
			    width: 200px;
			    height: 100%;
			    top: 0;
			    left: 0;
			    z-index: 1;
			}

			.slider:before,
			.slider:after {
			    position: absolute;
			    left: 50%;
			    content: "";
			    background: #fff;
			    cursor: grab;
			}

			.slider:before {
			    top: 0;
			    transform: translateX(-50%);
			    width: 1px;
			    height: 100%;
			}

			.slider:after {
			    top: 50%;
			    transform: translate(-50%, -50%);
			    width: 5px;
			    height: 33%;
			    border-radius: 5px;
			}

